1	// Command edgefleet is the 验证者与边缘节点机群管理平台 entry point.
2	package main
3	
4	import (
5		"flag"
6		"fmt"
7		"io"
8		"os"
9		"time"
10	
11		"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
12	)
13	
14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("edgefleet 0.1.0")
24		case "heartbeat":
25			runHeartbeat(os.Args[2:])
26		case "help", "-h", "--help":
27			usage()
28		default:
29			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
30			usage()
31			os.Exit(2)
32		}
33	}
34	
35	func usage() {
36		fmt.Println("usage: edgefleet [demo|version|heartbeat|help]")
37		fmt.Println()
38		fmt.Println("commands:")
39		fmt.Println("  demo       run the built-in evaluation demo")
40		fmt.Println("  version    print version")
41		fmt.Println("  heartbeat  receive, store and query real heartbeats")
42		fmt.Println("  help       show this help")
43		fmt.Println()
44		fmt.Println("run 'edgefleet heartbeat --help' for heartbeat input format and storage location")
45	}
