152	func newFlagSet(name string) *flag.FlagSet {
153		fs := flag.NewFlagSet(name, flag.ContinueOnError)
154		fs.SetOutput(os.Stderr)
155		fs.Usage = func() { heartbeatUsage() }
156		return fs
157	}
