159	func cmdSubmit(args []string) {
160		fs := newFlagSet("heartbeat submit")
161		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
162		receiveStr := fs.String("receive-time", "", "receive time (RFC3339); default: now")
163		if err := fs.Parse(args); err != nil {
164			if err == flag.ErrHelp {
165				os.Exit(0)
166			}
167			os.Exit(2)
168		}
169		if fs.NArg() != 0 {
170			die("submit takes no positional arguments; heartbeats are read from stdin")
171		}
172	
173		receiveTime := parseTimeFlag(*receiveStr, "--receive-time")
174	
175		data, err := io.ReadAll(os.Stdin)
176		if err != nil {
177			die("cannot read stdin: %v", err)
178		}
179		records, err := edgefleet.ParseHeartbeats(data, receiveTime)
180		if err != nil {
181			die("invalid input: %v", err)
182		}
183	
184		store, err := edgefleet.OpenStore(*dataDir)
185		if err != nil {
186			die("%v", err)
187		}
188		newCount, dupCount, err := store.Submit(records, receiveTime)
189		if err != nil {
190			die("%v", err)
191		}
192		fmt.Printf("submitted: new=%d duplicate=%d\n", newCount, dupCount)
193	}
