60	// runCLI invokes the re-executed binary with the given arguments. stdin is
61	// fed to the command (used by `heartbeat submit`). It returns the captured
62	// stdout, stderr and exit code.
63	func runCLI(t *testing.T, dir, stdin string, args ...string) (string, string, int) {
64		t.Helper()
65		cmd := exec.Command(os.Args[0], args...)
66		cmd.Stdin = strings.NewReader(stdin)
67		// Keep HOME inside the temp area too, so a missing --data-dir could never
68		// touch the developer's real ~/.edgefleet.
69		cmd.Env = append(os.Environ(),
70			cliTestEnv+"=1",
71			"HOME="+dir,
72			"EDGEFLEET_DATA_DIR="+filepath.Join(dir, "env-data"),
73		)
74		var out, errOut strings.Builder
75		cmd.Stdout = &out
76		cmd.Stderr = &errOut
77		err := cmd.Run()
78		code := 0
79		if err != nil {
80			var exitErr *exec.ExitError
81			if errors.As(err, &exitErr) {
82				code = exitErr.ExitCode()
83			} else {
84				t.Fatalf("failed to run helper binary: %v", err)
85			}
86		}
87		return out.String(), errOut.String(), code
88	}
