374	// nodeFileHexPath mirrors the per-node file naming used by the store.
375	func nodeFileHexPath(dir, node string) string {
376		return filepath.Join(dir, "nodes", hex.EncodeToString([]byte(node))+".json")
377	}
378	
379	// corruptNodeFile overwrites one node's saved file with raw content.
380	func corruptNodeFile(t *testing.T, dir, node, content string) {
381		t.Helper()
382		if err := os.WriteFile(nodeFileHexPath(dir, node), []byte(content), 0o644); err != nil {
383			t.Fatal(err)
384		}
385	}
386	
387	// readNodeFile returns the current raw bytes of a node's file.
388	func readNodeFile(t *testing.T, dir, node string) string {
389		t.Helper()
390		b, err := os.ReadFile(nodeFileHexPath(dir, node))
391		if err != nil {
392			t.Fatal(err)
393		}
394		return string(b)
395	}
