397	// strictChecksum replicates the store's checksum over the canonical JSON of a
398	// single record slice, so a test can forge a checksum matching a tampered
399	// interpretation. canonicalJSON must be the store's marshaled record form.
400	func strictChecksum(canonicalJSON string) string {
401		sum := sha256.Sum256([]byte(canonicalJSON))
402		return hex.EncodeToString(sum[:])
403	}
404	
405	// envelope wraps a raw records array in a well-formed store file.
406	func envelope(checksum, recordsJSON string) string {
407		return `{"format":"edgefleet-heartbeats-v1","checksum":"` + checksum + `","records":` + recordsJSON + `}`
408	}
