410	// TestCLIStoredCorruptionRefusedByQueries exercises the user-visible contract:
411	// a saved record with a missing, null or duplicated telemetry field corrupts
412	// the node's data even when the checksum matches the interpreted values; every
413	// query for that node fails on stderr with a non-zero exit and prints nothing
414	// on stdout, while other nodes keep working.
415	func TestCLIStoredCorruptionRefusedByQueries(t *testing.T) {
416		f := newFixture(t)
417	
418		const badRecord = `{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}`
419		submitBatch(t, f.dir, "["+badRecord+"]")
420	
421		cases := []struct {
422			name        string
423			tamper      string // raw records array stored alongside a matching checksum
424			interpreted string // canonical records a lenient reader reconstructs
425			wantField   string
426		}{
427			{
428				name:        "missing missed stays matching with original checksum",
429				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100}]`,
430				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`,
431				wantField:   "missed",
432			},
433			{
434				name:        "null height with checksum over zero-filled value",
435				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":null,"missed":0}]`,
436				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":0,"missed":0}]`,
437				wantField:   "height",
438			},
439			{
440				name:        "duplicate missed same value, last-wins interpretation matches",
441				tamper:      `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0,"missed":0}]`,
442				interpreted: `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`,
443				wantField:   "missed",
444			},
445		}
446	
447		for _, tc := range cases {
448			t.Run(tc.name, func(t *testing.T) {
449				// The forged checksum hashes the canonical record a lenient
450				// reader would reconstruct (zero-filled / last value).
451				corruptNodeFile(t, f.dir, "bad", envelope(strictChecksum(tc.interpreted), tc.tamper))
452	
453				// history: non-zero exit, explicit reason on stderr naming the
454				// file/record/field, no normal output on stdout.
455				out, errOut, code := runCLI(t, f.dir, "",
456					"heartbeat", "history", "--data-dir", f.dir, "--node", "bad")
457				if code == 0 {
458					t.Errorf("history on corrupt node must exit non-zero; stdout=%q", out)
459				}
460				if out != "" {
461					t.Errorf("history must print no results on corruption, stdout=%q", out)
462				}
463				if !strings.Contains(errOut, "error:") || !strings.Contains(errOut, "record 1") ||
464					!strings.Contains(errOut, tc.wantField) {
465					t.Errorf("history stderr must explain the corrupt record/field, got %q", errOut)
466				}
467				if !strings.Contains(errOut, filepath.Base(nodeFileHexPath(f.dir, "bad"))) {
468					t.Errorf("history stderr should identify the corrupt file, got %q", errOut)
469				}
470	
471				// health: same contract.
472				out, errOut, code = health(t, f,
473					"--node", "bad", "--expected-version", "1.26.0", "--tolerated-misses", "0")
474				if code == 0 {
475					t.Errorf("health on corrupt node must exit non-zero; stdout=%q", out)
476				}
477				if out != "" {
478					t.Errorf("health must print no results on corruption, stdout=%q", out)
479				}
480				if !strings.Contains(errOut, "record 1") || !strings.Contains(errOut, tc.wantField) {
481					t.Errorf("health stderr must explain the corrupt record/field, got %q", errOut)
482				}
483	
484				// health with a missed-duty baseline must fail identically rather
485				// than skipping the bad record.
486				out, errOut, code = health(t, f,
487					"--node", "bad", "--expected-version", "1.26.0",
488					"--tolerated-misses", "0", "--missed-since-seq", "1")
489				if code == 0 {
490					t.Errorf("baseline health on corrupt node must exit non-zero; stdout=%q", out)
491				}
492				if out != "" {
493					t.Errorf("baseline health must print no results on corruption, stdout=%q", out)
494				}
495				if !strings.Contains(errOut, tc.wantField) {
496					t.Errorf("baseline health stderr must name the field, got %q", errOut)
497				}
498			})
499		}
500	}
501	
502	// TestCLISubmitRejectsBatchTouchingCorruptNode ensures a batch is refused
503	// before any new record is saved: the corrupt file stays byte-for-byte
504	// intact, other files in the batch are not written, and no new node file is
505	// created. Submitting only to healthy nodes continues to work.
506	func TestCLISubmitRejectsBatchTouchingCorruptNode(t *testing.T) {
507		f := newFixture(t)
508	
509		const canonical = `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`
510		submitBatch(t, f.dir, "["+strings.Trim(canonical, "[]")+"]")
511		// Delete "missed" from the genuine record (its value was 0); keep the
512		// original checksum, which still matches the zero-filled interpretation.
513		corruptNodeFile(t, f.dir, "bad", envelope(strictChecksum(canonical),
514			`[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100}]`))
515	
516		badBefore := readNodeFile(t, f.dir, "bad")
517		monoBefore := readNodeFile(t, f.dir, "mono")
518	
519		batch := `[
520		  {"node":"bad","seq":2,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":102,"missed":0},
521		  {"node":"mono","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":104,"missed":15},
522		  {"node":"brandnew","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}
523		]`
524		out, errOut, code := runCLI(t, f.dir, batch,
525			"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
526		if code == 0 {
527			t.Errorf("submit touching a corrupt node must fail non-zero; stdout=%q stderr=%q", out, errOut)
528		}
529		if strings.Contains(out, "submitted") {
530			t.Errorf("rejected batch must not report success, stdout=%q", out)
531		}
532		if !strings.Contains(errOut, "corruption") || !strings.Contains(errOut, "missed") {
533			t.Errorf("submit stderr must explain the corruption, got %q", errOut)
534		}
535	
536		if got := readNodeFile(t, f.dir, "bad"); got != badBefore {
537			t.Errorf("corrupt node file was modified during rejected submit")
538		}
539		if got := readNodeFile(t, f.dir, "mono"); got != monoBefore {
540			t.Errorf("healthy node file was rewritten during rejected submit")
541		}
542		if _, err := os.Stat(nodeFileHexPath(f.dir, "brandnew")); !os.IsNotExist(err) {
543			t.Errorf("brand-new node file must not be created, stat err=%v", err)
544		}
545	
546		// Healthy nodes are unaffected and remain fully usable.
547		out, _, code = health(t, f,
548			"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
549		if code != 0 || !strings.Contains(out, "node=mono") {
550			t.Errorf("healthy node must still query normally: code=%d out=%q", code, out)
551		}
552		submitBatch(t, f.dir, `[{"node":"gappy","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":304,"missed":4}]`)
553	}
554	
555	// TestCLIMisownedNodeFileIsRefused plants one node's complete, checksum-valid
556	// file under another node's name and checks the command line refuses to serve
557	// it as the wrong node's telemetry: health (plain and with a baseline),
558	// history and submit all fail non-zero with the reason on stderr, while the
559	// real owner keeps working.
560	func TestCLIMisownedNodeFileIsRefused(t *testing.T) {
561		f := newFixture(t)
562	
563		// Copy mono's intact file over gappy's. Format and checksum stay valid;
564		// only the ownership is wrong.
565		corruptNodeFile(t, f.dir, "gappy", readNodeFile(t, f.dir, "mono"))
566		misownedPath := nodeFileHexPath(f.dir, "gappy")
567	
568		for _, tc := range []struct {
569			name string
570			args []string
571		}{
572			{"health", []string{"--node", "gappy", "--expected-version", "1.26.0", "--tolerated-misses", "9"}},
573			{"health with baseline", []string{"--node", "gappy", "--expected-version", "1.26.0", "--tolerated-misses", "9", "--missed-since-seq", "1"}},
574		} {
575			t.Run(tc.name, func(t *testing.T) {
576				out, errOut, code := health(t, f, tc.args...)
577				if code == 0 {
578					t.Fatalf("misowned file must fail the query, exit=0 stdout=%q", out)
579				}
580				if out != "" {
581					t.Errorf("no health result may be printed, stdout=%q", out)
582				}
583				for _, want := range []string{misownedPath, "record 1", `"gappy"`, `"mono"`} {
584					if !strings.Contains(errOut, want) {
585						t.Errorf("stderr must contain %s, got %q", want, errOut)
586					}
587				}
588			})
589		}
590	
591		out, errOut, code := runCLI(t, f.dir, "",
592			"heartbeat", "history", "--data-dir", f.dir, "--node", "gappy")
593		if code == 0 {
594			t.Fatalf("history of a misowned file must fail, exit=0 stdout=%q", out)
595		}
596		if out != "" {
597			t.Errorf("no history may be printed, stdout=%q", out)
598		}
599		if !strings.Contains(errOut, misownedPath) || !strings.Contains(errOut, `"mono"`) {
600			t.Errorf("history stderr must name the file and the foreign node, got %q", errOut)
601		}
602	
603		// A submit batch touching the misowned node is refused as a whole: no
604		// success line, no counts, and the first-time node in the batch is not
605		// created either.
606		batch := `[
607		  {"node":"gappy","seq":9,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":999,"missed":0},
608		  {"node":"brandnew","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}
609		]`
610		out, errOut, code = runCLI(t, f.dir, batch,
611			"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
612		if code == 0 {
613			t.Errorf("submit touching a misowned node must fail non-zero; stdout=%q", out)
614		}
615		if strings.Contains(out, "submitted") {
616			t.Errorf("rejected batch must not print success or counts, stdout=%q", out)
617		}
618		if !strings.Contains(errOut, misownedPath) {
619			t.Errorf("submit stderr must name the misowned file, got %q", errOut)
620		}
621		if _, err := os.Stat(nodeFileHexPath(f.dir, "brandnew")); !os.IsNotExist(err) {
622			t.Errorf("brand-new node file must not be created, stat err=%v", err)
623		}
624	
625		// The real owner of the copied records is unaffected.
626		out, _, code = health(t, f,
627			"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
628		if code != 0 || !strings.Contains(out, "node=mono") {
629			t.Errorf("real owner must still query normally: code=%d out=%q", code, out)
630		}
631	}
632	
633	// TestCLISubmitRejectsInvalidUTF8Node exercises the user-visible contract for
634	// a node id that is not losslessly representable text: the JSON input holds
635	// a raw invalid UTF-8 byte, which a lenient reader would silently rewrite to
636	// "�" and merge into another node. The whole batch must be refused with a
637	// non-zero exit, no success counts on stdout, an error naming the record and
638	// the node field on stderr, and no change to any stored data.
639	func TestCLISubmitRejectsInvalidUTF8Node(t *testing.T) {
640		f := newFixture(t)
641		monoBefore := readNodeFile(t, f.dir, "mono")
642	
643		badRecord := `{"node":"val-` + "\xff" + `1","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}`
644		goodRecord := `{"node":"mono","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":104,"missed":15}`
645		out, errOut, code := runCLI(t, f.dir, "["+goodRecord+","+badRecord+"]",
646			"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
647		if code == 0 {
648			t.Errorf("submit with an invalid UTF-8 node id must exit non-zero; stdout=%q", out)
649		}
650		if strings.Contains(out, "submitted") {
651			t.Errorf("rejected batch must not print success counts, stdout=%q", out)
652		}
653		if !strings.Contains(errOut, "record 2") || !strings.Contains(errOut, "node") {
654			t.Errorf("stderr must name the failing record and the node field, got %q", errOut)
655		}
656	
657		// The valid record in the same batch is not saved either.
658		if got := readNodeFile(t, f.dir, "mono"); got != monoBefore {
659			t.Errorf("existing node file changed during rejected submit")
660		}
661		if _, err := os.Stat(nodeFileHexPath(f.dir, "val-�1")); !os.IsNotExist(err) {
662			t.Errorf("no node file may be created for the rewritten id, stat err=%v", err)
663		}
664	
665		// Health answers for the existing node are unchanged.
666		out, _, code = health(t, f,
667			"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
668		if code != 0 || !strings.Contains(out, "seq=3") {
669			t.Errorf("health after rejected batch changed: code=%d out=%q", code, out)
670		}
671	}
672	
673	// TestCLISubmitRejectsUnpairedSurrogate covers the other silent rewrite: a
674	// \u escape that is an unpaired surrogate decodes to "�" instead of the
675	// intended character. The batch is refused and no node file is created.
676	func TestCLISubmitRejectsUnpairedSurrogate(t *testing.T) {
677		dir := t.TempDir()
678		batch := `[{"node":"val-\uD83D","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}]`
679		out, errOut, code := runCLI(t, dir, batch,
680			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
681		if code == 0 {
682			t.Errorf("submit with an unpaired surrogate must exit non-zero; stdout=%q", out)
683		}
684		if !strings.Contains(errOut, "record 1") || !strings.Contains(errOut, "node") {
685			t.Errorf("stderr must name the failing record and the node field, got %q", errOut)
686		}
687		// The batch is refused before the store is touched: no node file exists.
688		files, err := os.ReadDir(filepath.Join(dir, "nodes"))
689		if err != nil && !os.IsNotExist(err) {
690			t.Fatal(err)
691		}
692		if len(files) != 0 {
693			t.Errorf("no node file may be created, found %d", len(files))
694		}
695	}
696	
697	// TestCLISubmitValidUnicodeNodeRoundTrip checks the legal cases keep working
698	// end to end: a literal "�" is a valid character the user typed, an emoji
699	// written as a surrogate-pair escape is the same node as its literal form,
700	// and both are queryable by their original id.
701	func TestCLISubmitValidUnicodeNodeRoundTrip(t *testing.T) {
702		dir := t.TempDir()
703	
704		// Literal replacement character: a legal id, accepted as-is.
705		out, _, code := runCLI(t, dir,
706			`[{"node":"val-�","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}]`,
707			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
708		if code != 0 || !strings.Contains(out, "new=1") {
709			t.Fatalf("literal replacement char must be accepted: code=%d out=%q", code, out)
710		}
711	
712		// The same text as a � escape is the same node: duplicate, not new.
713		out, _, code = runCLI(t, dir,
714			`[{"node":"val-\uFFFD","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}]`,
715			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
716		if code != 0 || !strings.Contains(out, "new=0 duplicate=1") {
717			t.Errorf("escaped form of the same id must be a duplicate: code=%d out=%q", code, out)
718		}
719	
720		// An emoji written as a surrogate-pair escape is stored under the emoji.
721		out, _, code = runCLI(t, dir,
722			`[{"node":"val-\uD83D\uDE00","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":2,"missed":0}]`,
723			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
724		if code != 0 || !strings.Contains(out, "new=1") {
725			t.Fatalf("surrogate-pair escape must be accepted: code=%d out=%q", code, out)
726		}
727	
728		// Both nodes are queryable by their original ids.
729		out, _, code = runCLI(t, dir, "",
730			"heartbeat", "history", "--data-dir", dir, "--node", "val-�")
731		if code != 0 || !strings.Contains(out, "node=val-� seq=1") {
732			t.Errorf("history for literal replacement char id: code=%d out=%q", code, out)
733		}
734		out, _, code = runCLI(t, dir, "",
735			"heartbeat", "history", "--data-dir", dir, "--node", "val-😀")
736		if code != 0 || !strings.Contains(out, "node=val-😀 seq=1") {
737			t.Errorf("history for emoji id: code=%d out=%q", code, out)
738		}
739	}
