122	func TestSubmitNewAndDuplicate(t *testing.T) {
123		store, err := OpenStore(t.TempDir())
124		if err != nil {
125			t.Fatal(err)
126		}
127		receive := testBase
128		batch := []Heartbeat{
129			hb("n1", 1, receive.Add(-2*time.Minute), "1.0", 100, 0),
130			hb("n1", 2, receive.Add(-time.Minute), "1.0", 101, 0),
131			hb("n2", 5, receive.Add(-time.Minute), "2.0", 50, 3),
132		}
133		newC, dupC, err := store.Submit(batch, receive)
134		if err != nil {
135			t.Fatalf("submit failed: %v", err)
136		}
137		if newC != 3 || dupC != 0 {
138			t.Errorf("first submit: new=%d dup=%d, want 3/0", newC, dupC)
139		}
140	
141		// Re-submit the same records: all duplicates, nothing new.
142		newC, dupC, err = store.Submit(batch, receive)
143		if err != nil {
144			t.Fatalf("resubmit failed: %v", err)
145		}
146		if newC != 0 || dupC != 3 {
147			t.Errorf("resubmit: new=%d dup=%d, want 0/3", newC, dupC)
148		}
149	
150		// Same instant expressed in a different timezone is still a duplicate.
151		rebased := []Heartbeat{hb("n1", 1, receive.Add(-2*time.Minute).In(time.FixedZone("+08", 8*3600)), "1.0", 100, 0)}
152		newC, dupC, err = store.Submit(rebased, receive)
153		if err != nil {
154			t.Fatalf("rebased submit failed: %v", err)
155		}
156		if newC != 0 || dupC != 1 {
157			t.Errorf("rebased: new=%d dup=%d, want 0/1", newC, dupC)
158		}
159	}
