161	func TestSubmitConflict(t *testing.T) {
162		store, err := OpenStore(t.TempDir())
163		if err != nil {
164			t.Fatal(err)
165		}
166		receive := testBase
167		first := hb("n1", 1, receive.Add(-time.Minute), "1.0", 100, 0)
168		if _, _, err := store.Submit([]Heartbeat{first}, receive); err != nil {
169			t.Fatal(err)
170		}
171	
172		// Same node+seq, different version -> conflict, no overwrite.
173		conflict := hb("n1", 1, receive.Add(-time.Minute), "2.0", 100, 0)
174		_, _, err = store.Submit([]Heartbeat{conflict}, receive)
175		if err == nil {
176			t.Errorf("expected conflict error, got nil")
177		}
178	
179		// Original record unchanged.
180		hist, err := store.History("n1")
181		if err != nil {
182			t.Fatal(err)
183		}
184		if len(hist) != 1 || hist[0].Version != "1.0" {
185			t.Errorf("stored record changed after conflict: %+v", hist)
186		}
187	}
