	if code != 0 {
		t.Fatalf("valid batch after conflicts must succeed: code=%d stderr=%q", code, errOut)
	}
	if strings.TrimSpace(out) != "submitted: new=2 duplicate=0" {
		t.Errorf("stdout = %q, want new=2 duplicate=0", out)
