		t.Errorf("old seqs = %s, want 1,2", historySeqs(lines))
	}
	if lines := historyLines(t, dir, "fresh"); len(lines) != 1 || historySeqs(lines) != "1" {
		t.Errorf("fresh must have seq 1, got %q", strings.Join(lines, "\n"))
